import { useEffect, useState } from "react";
import { useAppStore } from "@/store";
import { bsc } from "@/shared/lib/core/bsc";
import { Box } from "@/shared/ui/layout/Box";
import { TerminalSlot } from "@/app/console/terminal/TerminalSlot";
import { StudioSessionMount, studioStartPrompt } from "@/features/studio-sessions/StudioSessionMount";
import { NetworkArchitectMount } from "@/features/studio-sessions/NetworkArchitectMount";
import { useStudioReaper } from "@/features/studio-sessions/useStudioReaper";
import { orderedWantedStudios } from "@/features/studio-sessions/store";
import { studioDetached, studioInitCmd } from "@/features/studio-sessions/lib/studioSessions";
import { systemSessionDef } from "@/shared/lib/session/systemSessionDefs";

/** Keep ONE SYSTEM session warm (`system-sessions-run-projects-and-start-when-visited`).
 *
 *  THE ONE LAUNCH PATH every system session shares. Its workspace is made by `bsc session prepare` through the
 *  generic `bsc` command — no Tauri setup command per session — with the persona's prompt (for a tutor, its
 *  protocol) handed over as the CONTEXT on stdin. The backend then resolves the whole launch from the pane id
 *  (`launch_plan::Identity::system`): role, persona, harness, model, directory. Nothing is seeded into the store
 *  and nothing is persisted, so there is nothing to go stale: the definition IS the configuration.
 *
 *  The same off-screen `primary parked` claim a studio mount holds, for the same reason: a visible viewer (the
 *  console) re-parents the terminal out of here, and this claim owns it only when it is the last one standing. */
function SystemSessionMount({ id }: { id: string }) {
  const def = systemSessionDef(id);
  // undefined = still preparing; null = prepare failed (no session); string = the workspace cwd.
  const [cwd, setCwd] = useState<string | null | undefined>(undefined);

  useEffect(() => {
    if (!def) return;
    let alive = true;
    void (async () => {
      let dir: string | undefined;
      try {
        const out = await bsc(null, ["session", "prepare", def.id, "--context", "-", "--json"], studioStartPrompt(def.personaId));
        dir = (JSON.parse(out) as { dir?: string }).dir;
      } catch (e) {
        console.error(`${def.id} workspace prepare failed:`, e);
      }
      if (!alive) return;
      setCwd(dir ?? null);
    })();
    return () => { alive = false; };
  }, [def]);

  if (!def || !cwd) return null;
  return (
    <Box
      aria-hidden
      data-testid={`system-session-mount-${def.id}`}
      style={{
        position: "absolute", left: -99999, top: 0, width: 800, height: 600,
        overflow: "hidden", pointerEvents: "none", display: "flex", flexDirection: "column",
      }}
    >
      <TerminalSlot paneId={def.paneId} primary parked visible={false} initialCwd={cwd} initCmd={studioInitCmd(def.harness)} />
    </Box>
  );
}

export function StudioSessionHosts() {
  useStudioReaper();
  const wantedStudios = useAppStore((s) => s.wantedStudios);
  const detachedSections = useAppStore((s) => s.detachedSections);
  const mounted = orderedWantedStudios(wantedStudios).filter((id) => !studioDetached(id, detachedSections));
  // Networks are NOT filtered by `studioDetached`: that reads `detachedSections` keyed by a studio's
  // `sectionId`, and a network has none. Nothing tears a network tab off into its own window today, and
  // wiring it through the studio key would match the wrong section rather than none.
  const networks = useAppStore((s) => s.wantedNetworkArchitects);
  // SYSTEM sessions, which the console opens. Not filtered by `studioDetached` either — a system session has
  // no page section to tear off.
  const systemSessions = useAppStore((s) => s.wantedSystemSessions);
  return (
    <>
      {mounted.map((id) => <StudioSessionMount key={id} studio={id} />)}
      {networks.map((id) => <NetworkArchitectMount key={id} networkId={id} />)}
      {systemSessions.map((id) => <SystemSessionMount key={id} id={id} />)}
    </>
  );
}
